//! Install embedded preset archives without overwriting user resources.
//! 安装内嵌的预设压缩包，不覆盖用户资源。

use std::{fs, io::Write, path::Path};

use super::{Error, Result, io_error};

/// Compressed Arch plugin generated by the Cargo build script.
/// Cargo 构建脚本生成的 Arch 插件压缩包。
const ARCH: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/arch.tar.gz"));

/// Atomically install the embedded Arch archive when its destination is absent.
/// 目标路径不存在时，以原子方式安装内嵌的 Arch 压缩包。
///
/// # Arguments
///
/// - `directory`: Existing plugin directory within the initialized workspace.
///   已初始化工作目录内的现有插件目录。
///
/// # Errors
///
/// Returns an error for a non-file destination or an archive write failure.
/// 目标不是普通文件或压缩包写入失败时返回错误。
pub(super) fn install(directory: &Path) -> Result<()> {
    let destination = directory.join("arch.tar.gz");
    match fs::symlink_metadata(&destination) {
        Ok(metadata) if metadata.is_file() && !metadata.file_type().is_symlink() => return Ok(()),
        Ok(_) => {
            return Err(Error::Invalid(format!(
                "预设插件路径必须是普通文件: {}",
                destination.display()
            )));
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(io_error(&destination, error)),
    }
    let mut temporary =
        tempfile::NamedTempFile::new_in(directory).map_err(|error| io_error(directory, error))?;
    temporary
        .write_all(ARCH)
        .map_err(|error| io_error(&destination, error))?;
    temporary
        .as_file()
        .sync_all()
        .map_err(|error| io_error(&destination, error))?;
    match temporary.persist_noclobber(&destination) {
        Ok(_) => Ok(()),
        Err(error) if error.error.kind() == std::io::ErrorKind::AlreadyExists => {
            let metadata = fs::symlink_metadata(&destination)
                .map_err(|error| io_error(&destination, error))?;
            if metadata.is_file() && !metadata.file_type().is_symlink() {
                Ok(())
            } else {
                Err(Error::Invalid(format!(
                    "预设插件路径必须是普通文件: {}",
                    destination.display()
                )))
            }
        }
        Err(error) => Err(io_error(&destination, error.error)),
    }
}
